-- missing), GetProfessionInfo gives name, icon, skill, max skill, ..., skill line.
local MY_PROFESSIONS = {
    [1] = { "Mining", 136248, 225, 300, 0, 0, 186 },
    [2] = { "Engineering", 136243, 210, 225, 0, 0, 202 },
    [5] = { "Cooking", 133971, 150, 225, 0, 0, 185 },
}
