    flush(); flush()
    check("a client that never says the guild bank opened is still read when its slots arrive", gbDB().tabs[1] ~= nil)
    closeBank()
    gbDB().tabs, gbDB().money, gbDB().access = {}, nil, {}
    gbSent()
    clearChat()

    local t0 = SERVER_NOW
