        local savedTell, savedParty = ChatFrame_SendTell, C_PartyInfo
        ChatFrame_SendTell = function(name) told = name end
        C_PartyInfo = { InviteUnit = function(name) invited = name end }
        click(card.whisper)
        click(card.invite)
