        win:GetWidth() == 840 and win:GetHeight() == 540 and fullPills == 3 and fullChips == 16 and win.logo:IsShown() and win.settingsChip:IsShown()
        and not ns.IsCompact() and ns.CompactView() == nil and ns.ExpandWindow() == false
