    table.insert(ROSTER, { "Nyfrelst-Stormrage", "Initiate", 4, 60, "Mage", "Orgrimmar", "", "", true, 0, "MAGE", guid = "Player-1-Nyfrelst" })
    fire("GUILD_ROSTER_UPDATE")
