        achDB().feed["name:annalind:J"] ~= nil and achDB().feed["name:annalind:J"].name == "Anna Lind"
        and achDB().feed["name:bolund:J"] ~= nil and achDB().feed["name:bolund:J"].name == "Bo Lund")
