        DrainBanners()
        pollReceive(P(b2, T + 1231, T + 1231 + DAY, "-", 2, "Borin-Stormrage", "Borins andre"), "Borin-Stormrage")
        pollReceive(O(b2, 1, "A", "B"), "Borin-Stormrage")
