        and w.plan.boss == "Edwin VanCleef" and w.plan.author == "Altine" and w.plan.updated == 123456 and w.plan.scenes[1] == nil
        and TAC.count("watch") == 1 and TAC.last("scene")[2] == 1)
    TAC.receive(show[2], "Altine-Stormrage")
