        and ed.noteBoxes[2]:GetText() == "Løp ut ved Inferno" and tip(ed.sceneChips[2]) == N.TAC_SCENE_N:format(2) .. " / Fase 2"
        and tip(ed.sceneNew) == N.TAC_SCENE_NEW .. " / " .. N.TAC_SCENE_NEW_TIP)
    press(ed.sceneChips[3])
