    end
    T.Preview(three(), 1)

    -- The window itself.
    do
        local listed = false
        for _, name in ipairs(UISpecialFrames) do listed = listed or name == "DragonworldTacticsViewer" end
        v:Fire("OnDragStart")
        v.points = { { "TOPLEFT", UIParent, "TOPLEFT", 40, -30 } }
        v:Fire("OnDragStop")
